typedef struct {char name[21];unsigned stock,price;} StockItem;
typedef struct {StockItem *data;size_t count,capacity;unsigned long revenue;} Shop;

int shop_init(Shop *s){s->count=s->capacity=0;s->revenue=0;s->data=malloc(2*sizeof *s->data);if(!s->data)return 0;s->capacity=2;return 1;}
void shop_destroy(Shop *s){free(s->data);s->data=NULL;s->count=s->capacity=0;s->revenue=0;}
int shop_find(const Shop *s,const char *n){for(size_t i=0;i<s->count;i++)if(!strcmp(s->data[i].name,n))return (int)i;return -1;}
int shop_add(Shop *s,const char *n,unsigned stock,unsigned price){size_t len=strlen(n);if(!len||len>20||stock>999||price>100000||s->count==20||shop_find(s,n)>=0)return 0;for(size_t i=0;i<len;i++)if(!isalpha((unsigned char)n[i]))return 0;if(s->count==s->capacity){size_t c=s->capacity*2;if(c>20)c=20;StockItem *p=realloc(s->data,c*sizeof *p);if(!p)return 0;s->data=p;s->capacity=c;}StockItem *p=s->data+s->count++;strcpy(p->name,n);p->stock=stock;p->price=price;return 1;}
int shop_restock(Shop *s,const char *n,unsigned count){int i=shop_find(s,n);if(i<0||count>999-s->data[i].stock)return 0;s->data[i].stock+=count;return 1;}
int shop_sell(Shop *s,const char *n,unsigned count){int i=shop_find(s,n);if(i<0||count>s->data[i].stock)return 0;unsigned long price=s->data[i].price;if(price&&count>(ULONG_MAX-s->revenue)/price)return 0;s->data[i].stock-=count;s->revenue+=price*count;return 1;}
int shop_save(const Shop *s,const char *path){FILE *f=fopen(path,"w");if(!f)return 0;int ok=fprintf(f,"%lu\n",s->revenue)>=0;for(size_t i=0;i<s->count;i++)if(fprintf(f,"%s,%u,%u\n",s->data[i].name,s->data[i].stock,s->data[i].price)<0)ok=0;if(fclose(f))ok=0;return ok;}
int shop_load(Shop *s,const char *path){FILE *f=fopen(path,"r");if(!f)return 0;Shop tmp;if(!shop_init(&tmp)){fclose(f);return 0;}char line[256],tail;int ok=fgets(line,sizeof line,f)&&sscanf(line,"%lu %c",&tmp.revenue,&tail)==1;while(ok&&fgets(line,sizeof line,f)){char name[21];unsigned stock,price;if(sscanf(line,"%20[A-Za-z],%u,%u %c",name,&stock,&price,&tail)!=3||!shop_add(&tmp,name,stock,price))ok=0;}if(ferror(f))ok=0;fclose(f);if(!ok){shop_destroy(&tmp);return 0;}shop_destroy(s);*s=tmp;return 1;}
